+/**
+ * Keep the prose for the current thinking step in a compact, newest-first
+ * preview. The live endpoint is bounded already; this keeps its many streamed
+ * lines from making the pill taller than its four-line body slot. Layout
+ * performs the visual clamp and tail anchoring, so this helper never clips the
+ * provider's prose.
+ */
+export function thinkingSummaryTail(value: unknown): string {
+  if (typeof value !== "string") return "";
+  const heading = [...value.matchAll(/\*\*(.+?)\*\*/gu)].at(-1);
+  const body = heading
+    ? value.slice((heading.index ?? 0) + heading[0].length)
+    : value;
+  return body.trim();
+}
